using System;using System.Diagnostics;using System.Text;using System.Text.RegularExpressions;using System.IO;
public sealed class ConnectionResult {public bool Success;public long Milliseconds;public string Message,Details;}
public static class ConnectionProbe {
 internal const string Command="printf 'AQSERVER_CONNECTION_OK\\n'";
 public static ConnectionResult Run(Server device){var server=device.Copy();if(server.IsLocal)return new ConnectionResult{Success=true,Message="本机可用 · 无需 SSH 连接",Details="本机模式直接读取 Windows 数据，不进行网络连接测试。"};var clock=Stopwatch.StartNew();try{if(!Regex.IsMatch(server.Host??"",@"^[a-zA-Z0-9._:-]+$")||!Regex.IsMatch(server.User??"",@"^[a-zA-Z0-9._-]*$")||server.Port<1||server.Port>65535)throw new InvalidOperationException("服务器地址、用户或端口无效");if(SshAuthentication.Managed(server)){string output=SshAuthentication.Execute(server,Command,12);clock.Stop();if(!Regex.IsMatch(output,@"(?m)^AQSERVER_CONNECTION_OK\r?$"))throw new IOException("SSH 未返回连接确认");return new ConnectionResult{Success=true,Milliseconds=clock.ElapsedMilliseconds,Message="SSH 连接成功 · "+clock.ElapsedMilliseconds+" ms",Details="耗时包含 SSH 握手、认证及轻量命令往返。"};}string args="-n -T -o BatchMode=yes -o ConnectTimeout=7 -o ConnectionAttempts=1 -o StrictHostKeyChecking=accept-new -p "+server.Port;if(!string.IsNullOrWhiteSpace(server.KeyPath))args+=" -i "+AqModuleSsh.Quote(Environment.ExpandEnvironmentVariables(server.KeyPath));args+=" -- "+AqModuleSsh.Quote(string.IsNullOrWhiteSpace(server.User)?server.Host:server.User+"@"+server.Host)+" "+AqModuleSsh.Quote(Command);using(var process=new Process{StartInfo=new ProcessStartInfo("ssh.exe",args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8}}){process.Start();var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(15000)){try{process.Kill();}catch{}throw new TimeoutException("SSH 连接超时");}clock.Stop();string output=stdout.Result,error=stderr.Result.Trim();if(process.ExitCode!=0||!Regex.IsMatch(output,@"(?m)^AQSERVER_CONNECTION_OK\r?$"))throw new IOException(string.IsNullOrEmpty(error)?"SSH 未返回连接确认 ("+process.ExitCode+")":error);return new ConnectionResult{Success=true,Milliseconds=clock.ElapsedMilliseconds,Message="SSH 连接成功 · "+clock.ElapsedMilliseconds+" ms",Details="耗时包含启动 SSH、握手、认证及轻量命令往返，并非 ICMP ping 延迟。\n目标："+server.Host+":"+server.Port};}}
 catch(Exception ex){clock.Stop();string reason=ex.Message.Trim();if(reason.Length>300)reason=reason.Substring(0,300);return new ConnectionResult{Success=false,Milliseconds=clock.ElapsedMilliseconds,Message="连接失败 · "+reason,Details="目标："+server.Host+":"+server.Port+"\n耗时 "+clock.ElapsedMilliseconds+" ms"};}}
}
